import numpy as np

# Test case 1: np.gcd with int32 MIN value and positive multiple
try:
    result = np.gcd(np.int32(np.iinfo(np.int32).min), np.int32(536870912) * 3)
    probe("np.gcd(np.int32(np.iinfo(np.int32).min), np.int32(536870912) * 3)", result)
except Exception as e:
    probe("np.gcd(np.int32(np.iinfo(np.int32).min), np.int32(536870912) * 3)", "__error__: " + type(e).__name__ + ": " + str(e))

# Test case 2: np.gcd with explicit INT_MIN value
try:
    result = np.gcd(np.int32(-2147483648), np.int32(1610612736))
    probe("np.gcd(np.int32(-2147483648), np.int32(1610612736))", result)
except Exception as e:
    probe("np.gcd(np.int32(-2147483648), np.int32(1610612736))", "__error__: " + type(e).__name__ + ": " + str(e))

# Test case 3: np.gcd with int32 MIN value as second argument
try:
    result = np.gcd(np.int32(536870912) * 3, np.int32(np.iinfo(np.int32).min))
    probe("np.gcd(np.int32(536870912) * 3, np.int32(np.iinfo(np.int32).min))", result)
except Exception as e:
    probe("np.gcd(np.int32(536870912) * 3, np.int32(np.iinfo(np.int32).min))", "__error__: " + type(e).__name__ + ": " + str(e))

# Test case 4: np.gcd with int64 MIN value
try:
    a = np.int64(np.iinfo(np.int64).min)
    b = -(a // 4) * 3
    result = np.gcd(a, b)
    probe("np.gcd(np.int64(np.iinfo(np.int64).min), -(np.int64(np.iinfo(np.int64).min) // 4) * 3)", result)
