    probe("np.gcd(np.int8(np.iinfo(np.int8).min), np.int8(42))", result)
except Exception as e:
    probe("np.gcd(np.int8(np.iinfo(np.int8).min), np.int8(42))", "__error__: " + type(e).__name__ + ": " + str(e))

